function Animal(name) { this.name = name; }
Animal.prototype.speak = function() { return this.name + ' makes a sound'; };
function Dog(name) { Animal.call(this, name); }
Dog.prototype = Object.create(Animal.prototype);
Dog.prototype.constructor = Dog;
Dog.prototype.speak = function() { return this.name + ' barks'; };
var d = new Dog('Rex');
console.log(d.speak());
console.log('proto === Dog.prototype:', Object.getPrototypeOf(d) === Dog.prototype);
console.log('Animal.prototype in chain:', Animal.prototype.isPrototypeOf(d));
console.log('d instanceof Dog:', d instanceof Dog);
console.log('d instanceof Animal:', d instanceof Animal);
console.log('own name:', d.hasOwnProperty('name'));
console.log('own speak?:', d.hasOwnProperty('speak'));
